INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT133-S3-Q1$batch13$, 133, 3, 1, $batch13$Role$batch13$, $batch13$Commentator: In last week's wreck involving one of Acme Engines' older locomotives, the engineer lost control of the train when his knee accidentally struck a fuel shut-down switch. Acme claims it is not liable because it never realized that the knee-level switches were a safety hazard. When asked why it relocated knee-level switches in its newer locomotives, Acme said engineers had complained that they were simply inconvenient. However, it is unlikely that Acme would have spent the $500,000 it took to relocate switches in the newer locomotives merely because of inconvenience. Thus, Acme Engines should be held liable for last week's wreck.$batch13$, $batch13$The point that Acme Engines spent $500,000 relocating knee-level switches in its newer locomotives is offered in the commentator's argument as$batch13$, $batch13$E$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=133 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$proof that the engineer is not at all responsible for the train wreck$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$a reason for believing that the wreck would have occurred even if Acme Engines had remodeled their older locomotives$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$an explanation of why the train wreck occurred$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$evidence that knee-level switches are not in fact hazardous$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$an indication that Acme Engines had been aware of the potential dangers of knee-level switches before the wreck occurred$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$Acme says it isn't liable because it never realized the knee-level switches were a hazard. It says it moved them in newer locomotives because engineers found them inconvenient.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$Acme should be held liable for the wreck.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$Acme spent $500,000 relocating the switches. It's unlikely a company would spend that much only to fix an inconvenience.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$The money is used to doubt Acme's story. If Acme wouldn't spend $500,000 for convenience, it probably moved the switches because it knew they were dangerous. That knowledge defeats Acme's defense, so Acme is liable.$batch13$), (4, $batch13$Goal$batch13$, $batch13$The $500,000 is a sign that Acme knew about the hazard before the wreck.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The argument never discusses the engineer's responsibility.$batch13$), ($batch13$B$batch13$, $batch13$Nothing suggests the wreck would have happened anyway.$batch13$), ($batch13$C$batch13$, $batch13$The wreck is explained by the knee hitting the switch. The money doesn't explain it.$batch13$), ($batch13$D$batch13$, $batch13$It's the reverse. The money suggests the switches were hazardous and that Acme knew it.$batch13$), ($batch13$E$batch13$, $batch13$A company doesn't spend $500,000 on an inconvenience, so Acme likely knew the switches were dangerous.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT133-S3-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
